import type { LicenceData } from "../../../scripts/licences/collect";

/**
 * The open source licences shipped with the app (generated by scripts/licences.mjs from the production dependencies).
 * The data is read the first time the licences screen needs it, not at start-up.
 */

export type Licence = { name: string; version: string; licence: string; text: number; copyright: string[]; author: string | null };
export type LicenceSection = { licence: string; packages: Licence[] };

/** Same marker and template rule as scripts/licences/collect.ts (which runs in Node and can't be bundled). */
const MARK = "\u0000";
const TEMPLATE_LINE = /\[(?:yyyy|year|name of copyright owner)\]|<(?:year|owner|copyright holders?)>|\{yyyy\}/i;

let cache: { data: LicenceData; packages: Licence[] } | null = null;

function load() {
  if (!cache) {
    const data = require("./licences.generated.json") as LicenceData;
    cache = { data, packages: data.packages.map(([name, version, licence, text, copyright, author]) => ({ name, version, licence, text, copyright, author: author ?? null })) };
  }
  return cache;
}

export const licencePackages = () => load().packages;

/** The full licence text for a package, with its copyright lines back where they were; null without a licence file. */
export function licenceText(entry: Licence, texts: readonly string[] = load().data.texts): string | null {
  const template = entry.text >= 0 ? texts[entry.text] : undefined;
  if (template == null) return null;
  let index = 0;
  return template.split("\n").map((line) => (line === MARK ? entry.copyright[index++] ?? "" : line)).join("\n");
}

/** The package's copyright holders (template lines left out), or its author when the licence names nobody. */
export function shownCopyright(entry: Licence): string | null {
  const lines = entry.copyright.flatMap((block) => block.split("\n")).filter((line) => !TEMPLATE_LINE.test(line));
  const unique = [...new Set(lines)];
  if (unique.length) return unique.join("\n");
  return entry.author ? `Author: ${entry.author}` : null;
}

/** Packages grouped by licence (most used first), filtered by name, licence or copyright holder. */
export function licenceSections(packages: Licence[], query = ""): LicenceSection[] {
  const search = query.trim().toLocaleLowerCase();
  const groups = new Map<string, Licence[]>();
  for (const entry of packages) {
    if (search && !entry.name.toLocaleLowerCase().includes(search) && !entry.licence.toLocaleLowerCase().includes(search) && !(shownCopyright(entry) ?? "").toLocaleLowerCase().includes(search)) continue;
    const list = groups.get(entry.licence) ?? [];
    list.push(entry);
    groups.set(entry.licence, list);
  }
  return [...groups].map(([licence, list]) => ({ licence, packages: list })).sort((a, b) => b.packages.length - a.packages.length || a.licence.localeCompare(b.licence));
}

export function findLicence(name: string, version: string) {
  return licencePackages().find((entry) => entry.name === name && entry.version === version) ?? null;
}

/** "(MIT OR Apache-2.0)" → "MIT or Apache-2.0". */
export const licenceName = (licence: string) => licence.replace(/^\((.*)\)$/, "$1").replace(/\bOR\b/g, "or").replace(/\bAND\b/g, "and");
